"""make damage list

    from result, make damage date to list

    Args
        find_list (list): score data, as raw data
    Returns
        ret (boolean): damage found or not found


    """
def make_damage_list(find_list: Any, damage: Any) -> object {
    ret = False;
    temp_list = [];
    list_num = len(find_list);
    for i in range(list_num) {
        if (find_list[i][0] != 0) {
            if not temp_list {
                temp_list = find_list[i];
                ret = True;
            }
            if (find_list[i][0] > (temp_list[0] + 5)) {
                damage.append(str(temp_list[1]));
                temp_list = find_list[i];
            } elif (find_list[i][2] > temp_list[2]) {
                temp_list = find_list[i];
            }
        }
    }
    if (ret is True) {
        damage.append(str(temp_list[1]));
    }
    return ret;
}

""" convert list of hex strings into list of ints """
def str_to_int(string_list: Any) -> object {
    int_list = [int(x, 16) for x in string_list];
    return int_list;
}

"""
    Next power of two for a given input, with a minimum of 16 and a
    maximum of 512

    Args:
        max_sent_tokens (int): the integer

    Returns:
        int: the appropriate power of two
    """
def next_pow_two(max_sent_tokens: Any) -> object {
    pow_two = [16, 32, 64, 128, 256, 512];
    if (max_sent_tokens <= pow_two[0]) {
        return pow_two[0];
    }
    if (max_sent_tokens >= pow_two[-1]) {
        return pow_two[-1];
    }
    check = [(max_sent_tokens > j) for j in pow_two];
    idx = check.index(False);
    return pow_two[idx];
}

"""
    get the number of games contained in the specified json data
    :param json_data: a string containing the json data retrieved from a previous web REST api call
    :return: returns the total number of games (0 if there are none)
    """
def get_games_count(json_data: Any) -> object {
    total_games = 0;
    if ('totalGames' in json_data) {
        total_games = int(json_data['totalGames']);
    }
    return total_games;
}

"""
    Returns a list of dictionaries.
    Each dictionary is the column name to its corresponding row value.
    """
def map_rows_to_cols(rows: Any, cols: Any) -> object {
    mapped_rows = [];
    for row in rows {
        mapped_rows.append({cols[i]: row[i] for i in range(len(cols))});
    }
    return mapped_rows;
}

