"""
    Return True if the coordinates are on the board, otherwise False.
    """
def isValidMove(x: Any, y: Any) -> object {
    return ((x >= 0) and (x <= 59) and (y >= 0) and (y <= 14));
}

"""
    Evaluate the polynomial P at x
    """
def poly_eval(P: Any, x: Any) -> object {
    out = 0;
    e = 1;
    for coef in P {
        out += coef * e;
        e *= x;
    }
    return out;
}

"""
        Quote unicode strings for URLs for Rocket
    """
def quote_unicode(s: Any) -> object {
    chars = [];
    for char in s {
        o = ord(char);
        if (o < 128) {
            chars.append(char);
        } else {
            chars.append(hex(o).replace("0x", "%").upper());
        }
    }
    return "".join(chars);
}

